// Banco de preguntas de Froxi.
// Cada pregunta tiene un TIPO y una DIFICULTAD:
//   Q(...)  pregunta facil              (dificultad 1)
//   M(...)  pregunta media              (dificultad 2)
//   D(...)  pregunta dificil            (dificultad 3)
//   T(dif, ...)  PREGUNTA TRAMPA: parece una cosa y es otra, hay que leer con cuidado
//   A(dif, ...)  ACERTIJO: hay que pensar
// La respuesta correcta SIEMPRE se escribe en 'correcta' (el juego mezcla las opciones solo).
// Cada nivel elige que dificultades usa con  dificultad = N  en su archivo Nivel_XX.cs:
//   dificultad = 2  ->  usa preguntas de dificultad 1 y 2
//   dificultad = 3  ->  usa preguntas de dificultad 2 y 3
public class Pregunta
{
    public string texto, correcta, mala1, mala2, explicacion;
    public string tipo = "Pregunta";   // Pregunta, Trampa o Acertijo
    public int dificultad = 1;         // 1 facil, 2 media, 3 dificil
}

public static class BancoPreguntas
{
    static Pregunta N(int dif, string tipo, string t, string ok, string m1, string m2, string exp)
    {
        return new Pregunta { dificultad = dif, tipo = tipo, texto = t, correcta = ok, mala1 = m1, mala2 = m2, explicacion = exp };
    }
    static Pregunta Q(string t, string ok, string m1, string m2, string exp) { return N(1, "Pregunta", t, ok, m1, m2, exp); }
    static Pregunta M(string t, string ok, string m1, string m2, string exp) { return N(2, "Pregunta", t, ok, m1, m2, exp); }
    static Pregunta D(string t, string ok, string m1, string m2, string exp) { return N(3, "Pregunta", t, ok, m1, m2, exp); }
    static Pregunta T(int dif, string t, string ok, string m1, string m2, string exp) { return N(dif, "Trampa", t, ok, m1, m2, exp); }
    static Pregunta A(int dif, string t, string ok, string m1, string m2, string exp) { return N(dif, "Acertijo", t, ok, m1, m2, exp); }

    // Devuelve que preguntas puede usar un nivel segun su 'dificultad' (0 = todas)
    public static bool Sirve(Pregunta p, int dificultadNivel)
    {
        if (dificultadNivel <= 0) return true;
        return p.dificultad == dificultadNivel || p.dificultad == dificultadNivel - 1;
    }

